#include <stdio.h>

int main(void) {
    int counts[10] = {0};
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int grade;
        scanf("%d", &grade);
        counts[grade]++;
    }
    for (int grade = 0; grade <= 10; grade++) {
        printf("%d%c", counts[grade], grade < 10 ? ' ' : '\n');
    }
    return 0;
}

